const e = $node["Extrair mensagem e origem"].json;
const texto = $node["Normalizar buffer"].json.texto;
return [{ json: { to: '<<RODRIGO_WA_NUMBER>>', tipo: 'text', texto: '⚠️ Sinal de sofrimento real detectado (P1).
Lead: ' + (e.nome || e.wa_id) + ' (' + e.wa_id + ')
Mensagem: "' + texto + '"
O agente ja parou de vender, acolheu e citou o CVV 188. Preciso que voce (ou alguem de confianca) assuma esta conversa agora.' } }];

// consumir_buffer devolve um ESCALAR (text ou null). O node HTTP do n8n nao
// entrega escalar como $json cru: dependendo da versao ele envelopa em
// { data: <valor> }. O codigo antigo fazia `const textoFinal = $node["Consumir
// buffer"].json` e mandava esse objeto direto como content da mensagem para a
// OpenAI. Aqui a forma e resolvida UMA vez, e o resto do fluxo le campos com nome.
const cru = $input.first().json;
let valor = cru;
if (cru && typeof cru === 'object' && !Array.isArray(cru)) {
  valor = ('data' in cru) ? cru.data : (Object.keys(cru).length === 0 ? null : cru);
}
if (Array.isArray(valor)) valor = valor[0];

// null = outra mensagem chegou durante a espera; quem responde e a mais recente.
const superada = (valor === null || valor === undefined);
const texto = superada ? '' : String(valor).trim();

return [{ json: { texto, superada, vazio: !superada && texto.length === 0 } }];
